import PDFDocument from "pdfkit";
import { Readable } from "stream";

export function generarPDF(datos, tipoTab) {
  const doc = new PDFDocument({ size: "A4", margin: 40 });
  const stream = new Readable({
    read() {},
  });

  doc.on("data", (chunk) => stream.push(chunk));
  doc.on("end", () => stream.push(null));

  doc.fontSize(18).text("Informe del Paciente", { align: "center" });
  doc.moveDown();
  doc.fontSize(12).text(`Fecha: ${new Date().toLocaleDateString()}`);
  doc.moveDown(2);

  switch (tipoTab) {
    case "diagnostico":
      doc.fontSize(14).text("Diagnóstico Médico", { underline: true });
      doc.moveDown();
      doc.fontSize(12).text(`Paciente: ${datos.nombre}`);
      doc.text(`Edad: ${datos.edad}`);
      doc.text(`Diagnóstico: ${datos.diagnostico}`);
      break;

    case "tratamiento":
      doc.fontSize(14).text("Plan de Tratamiento", { underline: true });
      doc.moveDown();
      doc.text(`Paciente: ${datos.nombre}`);
      doc.text(`Tratamiento: ${datos.tratamiento}`);
      doc.text(`Duración: ${datos.duracion}`);
      break;

    case "historial":
      doc.fontSize(14).text("Historial Clínico", { underline: true });
      doc.moveDown();
      datos.historial.forEach((item, i) => {
        doc.text(`${i + 1}. ${item.fecha} - ${item.detalle}`);
      });
      break;
    case "clinico":
      doc.fontSize(18).text("Clínico", { align: "center", underline: true });
      doc.moveDown(1.5);

      doc
        .fontSize(14)
        .text("Antecedentes de importancia:", { continued: true });
      doc
        .fontSize(12)
        .text(
          ` VASCULARES  TA: ${datos.clinico?.vasculares_ta || ""}  CARDIO: ${
            datos.clinico?.cardio || ""
          }`
        );
      doc.moveDown();

      doc.text(
        `V PERIF: ${datos.clinico?.vperif || ""}  edemas: ${
          datos.clinico?.edemas || ""
        }  úlceras: ${datos.clinico?.ulceras || ""}  DIGESTIVOS: ${
          datos.clinico?.digestivos || ""
        }`
      );
      doc.text(
        `Constipación: ${datos.clinico?.constipacion || ""}  RESPIRATORIAS: ${
          datos.clinico?.respiratorias || ""
        }`
      );
      doc.text(
        `METAB: ${datos.clinico?.metab || ""}  DBT: ${
          datos.clinico?.dbt || ""
        }  Tiroides: ${datos.clinico?.tiroides || ""}`
      );
      doc.text(
        `OSTEOMUSC: ${datos.clinico?.osteomusc || ""}  Articulaciones: ${
          datos.clinico?.articulaciones || ""
        }`
      );
      doc.text(
        `GINECOLÓGICAS: ${datos.clinico?.ginecologicas || ""}  UROLÓGICAS: ${
          datos.clinico?.urologicas || ""
        }`
      );
      doc.text(`Continencia: ${datos.clinico?.continencia || ""}`);
      doc.text(`DERMATOLÓGICAS: ${datos.clinico?.dermatologicas || ""}`);

      doc.text(
        `SENSORIALES  Auditivas: ${
          datos.clinico?.auditivas || ""
        }  Olfativas: ${datos.clinico?.olfativas || ""}  Visuales: ${
          datos.clinico?.visuales || ""
        }  Gustativas: ${datos.clinico?.gustativas || ""}`
      );
      doc.text(
        `SNC  Parálisis: ${datos.clinico?.paralisis || ""}  Parestesias: ${
          datos.clinico?.parestesias || ""
        }  Temblores: ${datos.clinico?.temblores || ""}  Convulsiones: ${
          datos.clinico?.convulsiones || ""
        }`
      );
      doc.text(
        `Afasias: ${datos.clinico?.afasias || ""}  Disartria: ${
          datos.clinico?.disartria || ""
        }`
      );

      doc.text(
        `Actitud psíquica  Activa: ${datos.clinico?.activa || ""}  Pasiva: ${
          datos.clinico?.pasiva || ""
        }`
      );

      doc.moveDown(2);
      doc.fontSize(14).text("Examen físico:", { underline: true });
      doc
        .fontSize(12)
        .text(
          `Fasciales: ${datos.clinico?.fasciales || ""}  Ojos: ${
            datos.clinico?.ojos || ""
          }  Boca: ${datos.clinico?.boca || ""}`
        );
      doc.text(`Dentición: ${datos.clinico?.denticion || ""}`);
      doc.text(`(…)`);
      break;

    default:
      doc.text("Sin datos específicos para este tab.");
  }

  doc.end();
  return stream;
}
